import csv
from datetime import datetime
from collections import defaultdict

CATS = {
    'taxi': 'Travel', 'uber': 'Travel', 'flight': 'Travel',
    'hotel': 'Lodging', 'airbnb': 'Lodging',
    'lunch': 'Meals', 'dinner': 'Meals', 'coffee': 'Meals',
    'saas': 'Software', 'software': 'Software', 'license': 'Software',
    'books': 'Learning', 'course': 'Learning',
}
def parse_date(value):
    for fmt in ('%Y-%m-%d', '%m/%d/%Y', '%d %b %Y'):
        try: return datetime.strptime(value.strip(), fmt).date()
        except ValueError: pass
    raise ValueError(value)
def cents(value):
    value = value.strip().replace('USD', '').replace('$', '').replace(',', '').strip()
    whole, _, frac = value.partition('.')
    return int(whole) * 100 + int((frac + '00')[:2])

rows = list(csv.DictReader(open('expenses.csv', newline='', encoding='utf-8')))
seen, calc, flags = set(), defaultdict(lambda: [0, 0]), []
for row in rows:
    rid = int(row['id'])
    date = parse_date(row['date'])
    if (date.month, date.year) != (10, 2026):
        continue
    if row['status'].strip().lower() == 'void' or rid in seen:
        continue
    seen.add(rid)
    amount = cents(row['amount'])
    category = CATS[row['category'].strip().lower()]
    calc[category][0] += 1
    calc[category][1] += amount
    if amount > 50000:
        flags.append((rid, amount))

total = sum(v[1] for v in calc.values())
out = [f'# Expense Report — October 2026', f'Total: ${total / 100:,.2f}', '', '| Category | Items | Amount |', '|---|---:|---:|']
for category, (count, amount) in sorted(calc.items(), key=lambda kv: (-kv[1][1], kv[0])):
    out.append(f'| {category} | {count} | ${amount / 100:,.2f} |')
out += ['', '## Flags']
if flags:
    for rid, amount in sorted(flags):
        out.append(f'- #{rid} ${amount / 100:,.2f} — over $500, receipt required')
else:
    out.append('- none')

expected = '\n'.join(out) + '\n'
actual = open('report.md', encoding='utf-8').read()
if actual != expected:
    import difflib
    print('MISMATCH')
    print(''.join(difflib.unified_diff(expected.splitlines(True), actual.splitlines(True), fromfile='expected', tofile='actual')))
    raise SystemExit(1)

assert sum(v[1] for v in calc.values()) == total
print(f'OK: {len(seen)} items; category sum equals total ${total / 100:,.2f}; flags={[rid for rid, _ in sorted(flags)]}')
PY", "description": "Recompute and compare report exactly"}

